"""Render measured boundary studies without promoting any candidate."""
import html
import shutil
from strep import ROOT,read,save


def build():
    out=ROOT/'reports/boundary-guidance-v1';rows=[]
    for study,label in [('boundary-guides-v2','Root / context'),('boundary-guidance-v1','Guidance weight')]:
        folder=ROOT/'reports'/study
        verified={r['id']:r for r in read(folder/'verification.json')['cases']}
        for row in read(folder/'comparison.json')['cases']:
            key=row['case']+'-'+row['mode'];r=read(folder/key/'record.json');v=verified[key]
            path='../'+study+'/'+key+'/'
            rows.append(f'''<tr data-case="{html.escape(row['case'])}"><td>{html.escape(row['case'])}</td><td>{label} / {html.escape(row['mode'])}</td><td>{row['common_anchors_position_head']['max_joint_error_m']*1000:.2f}</td><td class="failed">{row['common_anchors_rotation_fk']['max_joint_error_m']*1000:.2f}</td><td>{row['native_mesh_floor_m']*1000:.2f}</td><td>{v['boundary_eight_frame_step_max_degrees']:.2f}</td><td><a href="{path}record.json">Record</a> · <a href="{path}soma.glb" download>GLB</a> · <a href="{path}motion.npz" download>NPZ</a></td></tr>''')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Strep · Boundary conditioning study</title><style>body{font:14px system-ui;background:#e8edf5;color:#263447;margin:0}main{max-width:1200px;margin:30px auto;padding:25px;background:#ffffffdf;border:1px solid white;border-radius:18px}h1{font-size:26px}p{line-height:1.6;max-width:980px}.status{background:#fff0db;border:1px solid #dbbb8c;border-radius:10px;padding:14px;color:#754b13}.table{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px;border-bottom:1px solid #d9e1ec;text-align:right;font-variant-numeric:tabular-nums}th:first-child,td:first-child,td:nth-child(2){text-align:left}.failed{color:#a53224;font-weight:650}select{font:inherit;padding:8px;border:1px solid #bdcbdc;border-radius:8px;background:white}a{color:#175fa9}.links{display:flex;gap:18px;flex-wrap:wrap}</style><main><h1>Boundary conditioning: what actually failed</h1><p class="status">24 model runs, no candidate passes the 30 mm boundary screen. Current production settings remain unchanged.</p><p>Six baseline replays reproduce the original NPZ bytes exactly. Independent decoding confirms that the guide positions reach the model within 0.003 mm. The model's predicted positions already miss the target; reconstructing the skeleton from predicted rotations adds a second error. Full-body guides do not explicitly constrain rotations.</p><p>Eight-frame boundary context slightly improves the jump and worsens the dance. Recomputing the smoothed root does not consistently help. Raising constraint guidance from 2 to 3, 4 or 6 also produces regressions. These are reused failures across two actions and two rig families, not held-out evidence or a realism score.</p><label>Case <select id="case"><option value="">All cases</option><option>jump-205</option><option>jump-204</option><option>dance-203</option><option>dance-204</option></select></label><div class="table"><table><thead><tr><th>Case</th><th>Experiment</th><th>Position-head error (mm)</th><th>Rotation / FK error (mm)</th><th>Native floor depth (mm)</th><th>Boundary joint step (°)</th><th>Exact output</th></tr></thead><tbody>'''+''.join(rows)+'''</tbody></table></div><p>Both error columns use the same four original boundary frames, including the longer-context variants. The full audits also measure every additional guide. Floor depth uses the native SOMA skin, not a retargeted character. Joint steps are diagnostic; low floor error or successful export does not prove action completion or naturalness.</p><p class="links"><a href="verification.json">Guidance verification</a><a href="../boundary-guides-v2/verification.json">Root/context verification</a><a href="export-validation.json">GLB validation</a><a href="../rig-clearance-v3/viewer.html">Prior mesh correction comparison</a><a href="http://127.0.0.1:8768/studio">Studio</a></p><p>Next: build and evaluate the pinned NVIDIA motion-correction extension on these exact raw samples before pursuing a learned editor. It is not installed on this laptop; CMake and a C++ compiler are also absent. Checkpoint, source motion and production paths have not been changed.</p><p>Native preview asset: NVIDIA Kimodo, Apache-2.0. <a href="SOMA-preview-LICENSE.txt">Preview license</a> · <a href="Kimodo-model-LICENSE.txt">Checkpoint license</a>. Model uses validated cached text conditioning; full resident-encoder equivalence and independent animator review remain untested.</p></main><script>document.getElementById('case').onchange=e=>{for(const row of document.querySelectorAll('tbody tr'))row.hidden=!!e.target.value&&row.dataset.case!==e.target.value;};</script></html>'''
    (out/'review.html').write_text(page,encoding='utf8')
    shutil.copyfile(ROOT/'vendor/kimodo/LICENSE',out/'SOMA-preview-LICENSE.txt')
    shutil.copyfile(ROOT/'models/checkpoints/Kimodo-SOMA-RP-v1.1/LICENSE',out/'Kimodo-model-LICENSE.txt')
    save(out/'decision.json',dict(production_settings_changed=False,training=False,inference_runs=24,baseline_replays=6,all_baseline_npz_bytes_identical=True,all_raw_boundary_screens_failed=True,next='Build pinned official MotionCorrection extension and compare deterministic correction on retained raw outputs; do not call this a trained editor.',limitations=['Only two known descriptions, two existing rig families','No independent semantic or animator review','Native floor is separate from target-rig clearance','Text encoder full resident equivalence remains untested']))


if __name__=='__main__':build()
